INSERT INTO `fbsv2_sending_email_log` (`sending_email_log_aid`, `sending_email_log_is_active`, `sending_email_log_audience_id`, `sending_email_log_email`, `sending_email_log_subject`, `sending_email_log_content`, `sending_email_log_is_success`, `sending_email_log_key`, `sending_email_log_firstname`, `sending_email_log_role`, `sending_email_log_firstname_resend`, `sending_email_log_role_resend`, `sending_email_log_created`, `sending_email_log_datetime`) VALUES
(39, 1, 13, 'louren.rubico@frontlinebusiness.com.ph', 'FBS Newsletter: March 2025', '<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <!--Dark Mode meta tags needed to enable Dark Mode in email client user agents-->\n    <meta name=\"color-scheme\" content=\"light dark\" />\n    <meta name=\"supported-color-schemes\" content=\"light dark only\" />\n\n    <title>FBS Marketing Website Newsletter</title>\n    <!-- CSS -->\n    <style>\n      :root {\n        color-scheme: light dark;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n        /* outline: 1px solid red; */\n      }\n      body {\n        font-family: Arial, Helvetica, sans-serif !important;\n        color: #333;\n      }\n      .canvas {\n        width: 700px;\n        margin: 0 auto;\n        background-color: #f9f9f9;\n      }\n      table {\n        border-spacing: 0;\n      }\n      .partnerMobile {\n        display: none;\n      }\n      .partnerDesktop {\n        display: block;\n      }\n      .renewalMobile {\n        display: none;\n      }\n      .renewalDesktop {\n        display: block;\n      }\n      .partnerMobile--block1 img {\n        width: 100% !important;\n      }\n      @media screen and (min-width: 340px) and (max-width: 520px) {\n        .canvas {\n          width: 100% !important;\n          background-color: #f9f9f9 !important;\n        }\n        .container {\n          width: 100% !important;\n          padding: 0 !important;\n          margin: 0 auto !important;\n        }\n        .newsLetter {\n          padding: 0 !important;\n        }\n        table {\n          width: 520px !important;\n        }\n        .title {\n          padding: 0 !important;\n          background-size: 100vw !important;\n          height: 127px !important;\n        }\n\n        .partnerMobile {\n          display: block;\n        }\n        .partnerDesktop {\n          display: none;\n        }\n\n        .fellowship img {\n          width: 100% !important;\n        }\n      }\n    </style>\n  </head>\n  <body>\n    <section class=\"newsLetter\" style=\"background-color: white; padding: 0\">\n      <div\n        class=\"container\"\n        style=\"width: 700px; margin: 0 auto; background-color: white\"\n      >\n        <div class=\"canvas\">\n          <!-- TITLE -->\n          <div\n            class=\"title\"\n            style=\"\n              background-image: url(\'https://lh3.googleusercontent.com/pw/AP1GczO2mnGZ7Yj2iGNuE2ljfUdDewsjbR3GzQPNmmt7SBX9DBXziGh-or05nDOyaQQyAJS-IdnVYcXnpZpcZQB-McNi7ivOGWZc5sAzcShUFGWfO_DwkR4=w2400\');\n              background-repeat: no-repeat;\n              background-size: cover;\n              background-position: center;\n              height: 205px;\n              border: none;\n            \"\n          ></div>\n          <!-- BACKGROUND IMAGE -->\n          <div\n            class=\"imageSeperator\"\n            style=\"\n              background-image: url(\'https://lh3.googleusercontent.com/pw/AP1GczP5vUUM81NlJQeVvXKTY8PKUBuld07dmr9pEWvV-69YsMj8d0dUxXyQwCTAac9CchHOSnRfeL-bA6QVLNscCYcL8BJrHEEuBLNAz85g5AX9zzMS39Y=w2400\');\n              background-repeat: no-repeat;\n              background-size: cover;\n              background-position: center;\n              height: 350px;\n              border: none;\n            \"\n          ></div>\n          <!-- DESC -->\n          <div\n            class=\"desc\"\n            style=\"padding: 48px 17px; background-color: #f2f2f2\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                line-height: 30px;\n                margin-bottom: 1px;\n                margin-top: 0;\n              \"\n            >\n              DepEd\'s Revamped Senior High School Curriculum\n            </h2>\n            <small style=\"font-size: 14px; font-weight: 600; color: #d60070\">\n              Enhancing Employability of SHS Graduates\n            </small>\n\n            <p style=\"font-size: 14px; margin: 20px 0\">\n              The Department of Education (DepEd) is set to implement a major\n              revision of the Senior High School (SHS) curriculum starting in\n              School Year (SY) 2025-2026, aiming to enhance graduates\'\n              employability by reducing core subjects from 15 to just five or\n              six. This change will allocate more time for work immersion and\n              on-the-job training, ensuring students gain practical skills\n              aligned with industry needs. To facilitate a smooth transition, a\n              phased implementation approach will be adopted. DepEd is\n              collaborating with industry experts to refine standards in key\n              subjects like English, Science, and Mathematics, making education\n              more responsive to workforce demands. Industry partnerships, such\n              as those with Frontline Business Solutions, play a crucial role in\n              this initiative by providing students with real-world experience\n              in fields like IT, Accounting, and Administrative work, ultimately\n              preparing them for successful careers. Schools interested in\n              partnering with Frontline Business Solutions can explore their\n              work immersion program for enhanced hands-on training\n              opportunities.\n            </p>\n\n            <div style=\"text-align: center; margin-top: 26px\">\n              <a\n                class=\"btn\"\n                href=\"https://frontlinebusiness.com.ph/insight/DepEd%E2%80%99s%20Revamped%20Senior%20High%20School%20Curriculum:%20Enhancing%20Employability%20of%20SHS%20Graduates\"\n                style=\"\n                  display: inline-block;\n                  color: #dbd5d5;\n                  font-weight: 300;\n                  padding: 12px 50px;\n                  background: linear-gradient(to right, #d60070, #6a1142);\n                  border-radius: 5px;\n                  text-decoration: none;\n                  font-size: 12px;\n                \"\n                >Read more</a\n              >\n            </div>\n          </div>\n          <!-- TWO MILES -->\n          <div\n            class=\"twoMiles\"\n            style=\"padding: 48px 17px; background-color: #fef7ed\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                line-height: 30px;\n                margin-bottom: 1px;\n                margin-top: 0;\n              \"\n            >\n              Two Miles Inc. Founder Hiro Isogawa Visits <br />\n              FBS for Annual Accounting Team Engagement\n            </h2>\n            <small style=\"font-size: 14px; font-weight: 600; color: #d60070\">\n              Accounting Solutions\n            </small>\n            <div style=\"text-align: center; margin: 20px 0\">\n              <img\n                src=\"https://lh3.googleusercontent.com/pw/AP1GczMIzjo4QMUsIfXs7JcElbsLwLyKgtVz-GOvPKPkJMrXJy_x5iW51idYT78wgckP5rp6qSrdvlQ1h31aGPQCvbEg8tYVVbHxMhMuGpYX8ndnBrP81rA=w2400\"\n                alt=\"\"\n                style=\"width: 208px\"\n              />\n            </div>\n\n            <p style=\"font-size: 14px; margin: 20px 0\">\n              Hiro Isogawa, founder of Two Miles Inc., recently visited\n              Frontline Business Solutions (FBS) for his annual engagement with\n              the accounting team, reinforcing their strong partnership in\n              outsourced bookkeeping, payroll, tax compliance, and\n              administrative support. His visit highlighted the growing\n              workforce at FBS, acknowledging their contributions and discussing\n              strategies for improving efficiency, while this annual tradition\n              reflects the trust and confidence in FBS, fostering professional\n              ties and motivating the team to continue delivering high-quality\n              accounting services.\n            </p>\n            <img\n              src=\"https://lh3.googleusercontent.com/pw/AP1GczN-_89rNMne59u8l2y-GahjBoalmhSbBqotO--mKRMPbfJwCOUpP84abBvXk00KkVqIjm7SUHh0618jGyCs6psUooMRygMbBoFsmOSqcvDDZphN3hE=w2400\"\n              alt=\"\"\n              style=\"\n                width: 100%;\n                height: 350px;\n                object-fit: cover;\n                display: block;\n              \"\n            />\n\n            <div style=\"text-align: center; margin-top: 26px\">\n              <a\n                class=\"btn\"\n                href=\"https://frontlinebusiness.com.ph/events-and-activities/Two-Miles-Inc.-Founder-Hiro-Isogawa-Visits-FBS-for-Annual%20-Accounting-Team-Engagement\"\n                style=\"\n                  display: inline-block;\n                  color: #dbd5d5;\n                  font-weight: 300;\n                  padding: 12px 50px;\n                  background: linear-gradient(to right, #d60070, #6a1142);\n                  border-radius: 5px;\n                  text-decoration: none;\n                  font-size: 12px;\n                \"\n                >Read more</a\n              >\n            </div>\n          </div>\n          <!-- NEW PARTNER DESKTOP -->\n          <div\n            class=\"partnerDesktop\"\n            style=\"padding: 48px 17px; background-color: #f2f2f2\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                line-height: 30px;\n                margin-bottom: 1px;\n                margin-top: 0;\n              \"\n            >\n              STI College San Pablo Kicks Off SHS Work Immersion at FBS\n            </h2>\n            <small style=\"font-size: 14px; font-weight: 600; color: #d60070\">\n              Learning Center Solutions Service\n            </small>\n\n            <table\n              cellpadding=\"0\"\n              cellspacing=\"0\"\n              role=\"presentation\"\n              style=\"\n                width: 683px;\n                height: 0px;\n                padding-top: 32px;\n                text-align: center;\n              \"\n            >\n              <tr>\n                <td style=\"vertical-align: top\" width=\"50%\">\n                  <a href=\"#\">\n                    <img\n                      src=\"https://lh3.googleusercontent.com/pw/AP1GczPw-vtzFlicJONf2Lrf6GoFlUhisEzRw9TNx_imJv4tZYqd4W5foO_HZcmMkb-L-n8pF1UMCbEn0mwBTINMuTr7uTATrPnWfmOZxIFlckC1rXf1c5w=w2400\"\n                      alt=\"\"\n                      style=\"display: block; width: 317px\"\n                    />\n                  </a>\n                  <div style=\"text-align: center; margin-top: 26px\">\n                    <a\n                      class=\"btn\"\n                      href=\"https://frontlinebusiness.com.ph/events-and-activities/STI-College-Work-Immersion-Kicks-Off\"\n                      style=\"\n                        display: inline-block;\n                        color: #dbd5d5;\n                        font-weight: 300;\n                        padding: 12px 50px;\n                        background: linear-gradient(to right, #d60070, #6a1142);\n                        border-radius: 5px;\n                        text-decoration: none;\n                        font-size: 12px;\n                      \"\n                      >Read more</a\n                    >\n                  </div>\n                </td>\n                <td style=\"vertical-align: top\" width=\"50%\">\n                  <p style=\"text-align: left; padding-right: 20px\">\n                    STI College San Pablo\'s Grade 12 ICT students have\n                    officially begun their 80-hour Work Immersion Program in Web\n                    Design and Web Development! Guided by industry\n                    professionals, students will gain hands-on experience using\n                    Figma for UI/UX design and HTML & CSS for web development,\n                    bridging the gap between academics and real-world\n                    application.\n                  </p>\n                </td>\n              </tr>\n            </table>\n          </div>\n          <!-- NEW PARTNER MOBILE -->\n          <div\n            class=\"partnerMobile\"\n            style=\"padding: 48px 17px; background-color: #f2f2f2\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                line-height: 30px;\n                margin-bottom: 1px;\n                margin-top: 0;\n              \"\n            >\n              STI College San Pablo Kicks Off SHS Work Immersion at FBS\n            </h2>\n            <small style=\"font-size: 14px; font-weight: 600; color: #d60070\">\n              Learning Center Solutions Service\n            </small>\n\n            <div\n              class=\"partnerMobile--block1\"\n              style=\"list-style: none; text-align: center; margin-top: 32px\"\n            >\n              <a href=\"#\">\n                <img\n                  src=\"https://lh3.googleusercontent.com/pw/AP1GczPw-vtzFlicJONf2Lrf6GoFlUhisEzRw9TNx_imJv4tZYqd4W5foO_HZcmMkb-L-n8pF1UMCbEn0mwBTINMuTr7uTATrPnWfmOZxIFlckC1rXf1c5w=w2400\"\n                  alt=\"\"\n                  style=\"display: block; width: 317px\"\n                />\n              </a>\n              <div style=\"text-align: center; margin: 26px 0\">\n                <a\n                  class=\"btn\"\n                  href=\"https://frontlinebusiness.com.ph/events-and-activities/STI-College-Work-Immersion-Kicks-Off\"\n                  style=\"\n                    display: inline-block;\n                    color: #dbd5d5;\n                    font-weight: 300;\n                    padding: 12px 50px;\n                    background: linear-gradient(to right, #d60070, #6a1142);\n                    border-radius: 5px;\n                    text-decoration: none;\n                    font-size: 12px;\n                  \"\n                  >Read more</a\n                >\n              </div>\n              <p style=\"text-align: left\">\n                STI College San Pablo\'s Grade 12 ICT students have officially\n                begun their 80-hour Work Immersion Program in Web Design and Web\n                Development! Guided by industry professionals, students will\n                gain hands-on experience using Figma for UI/UX design and HTML &\n                CSS for web development, bridging the gap between academics and\n                real-world application.\n              </p>\n            </div>\n          </div>\n          <!-- WELCOME VISITORS -->\n          <div\n            class=\"welcomeVisitors\"\n            style=\"padding: 48px 17px; background-color: #fef7ed\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                line-height: 30px;\n                margin-bottom: 1px;\n                margin-top: 0;\n              \"\n            >\n              FBS Welcomes Visitors from Prairie Harvest Christian Life Centre\n            </h2>\n            <small style=\"font-size: 14px; font-weight: 600; color: #d60070\">\n              Company Culture and Values\n            </small>\n            <div style=\"text-align: center; margin: 20px 0\">\n              <img\n                src=\"https://lh3.googleusercontent.com/pw/AP1GczN5KlcT-jp0aQWKgb2BC1MhX1FPRVoR3Nu_g2c6FEd0t8RmapmGiWt8KzWC1slJGniMm3uYHHjZFl99gmG0-bNcRYhHp68iCTS56c_YCONCWjLRHD8=w2400\"\n                alt=\"\"\n                style=\"width: 300px\"\n              />\n            </div>\n\n            <p style=\"font-size: 14px; margin: 20px 0\">\n              FBS, a Christ-centered company, was honored to welcome Ptr. Des\n              Klingspon from Prairie Harvest Christian Life Centre in Yorkton,\n              Saskatchewan, Canada, along with Bro. Stefan and Sis. Chrystal\n              Bymak. Through our partnership with Philippine Frontline\n              Ministries and various churches, we continue to integrate faith\n              into our workplace and community, striving to serve with\n              excellence, honor God, and make a lasting impact.\n            </p>\n            <img\n              src=\"https://lh3.googleusercontent.com/pw/AP1GczP57vfhFKQ2qZlkjAF1KPu8dv49XIip9XU83k4Nwr3zQ7jfD2TdbXMYDCJCAdjd54NA7kYXfMx9RcRSU_iIR-JZddEufU_FjQbDeQj1_ThG5wUwWIU=w2400\"\n              alt=\"\"\n              style=\"\n                width: 100%;\n                height: 350px;\n                object-fit: cover;\n                display: block;\n              \"\n            />\n            <div style=\"text-align: center; margin-top: 26px\">\n              <a\n                class=\"btn\"\n                href=\"https://frontlinebusiness.com.ph/events-and-activities/FBS-Welcomes-Visitors-from-Prairie-Harvest-Christian-Life-Centre\"\n                style=\"\n                  display: inline-block;\n                  color: #dbd5d5;\n                  font-weight: 300;\n                  padding: 12px 50px;\n                  background: linear-gradient(to right, #d60070, #6a1142);\n                  border-radius: 5px;\n                  text-decoration: none;\n                  font-size: 12px;\n                \"\n                >Read more</a\n              >\n            </div>\n          </div>\n          <!-- FELLOWSHIP -->\n          <div\n            class=\"fellowship\"\n            style=\"padding: 48px 17px; background-color: #f2f2f2\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                line-height: 30px;\n                margin-bottom: 1px;\n                margin-top: 0;\n              \"\n            >\n              March Company Fellowship\n            </h2>\n            <small style=\"font-size: 14px; font-weight: 600; color: #d60070\">\n              Company Culture and Team Building\n            </small>\n            <p style=\"font-size: 14px; margin: 20px 0\">\n              As February is known as the month of love, Frontline Business\n              Solutions, Inc. embraced this spirit of unity and camaraderie\n              through our monthly company fellowship. With the theme \"Raising\n              the Bar, Reaching Far, the event served as a reminder of our\n              commitment to continuous growth, excellence, and teamwork.\n            </p>\n            <a href=\"#\">\n              <img\n                src=\"https://lh3.googleusercontent.com/pw/AP1GczOVfQR1PzObsu1YM22xOmaf1oiuDc-uR1WKU9j2waI9Mx2MGW5YXtch6h8PI_8bIlcknfd2_P9IjTNx0Ovb6DlB4XhukBJcdzU1yT0snlwapC8fh-8=w2400\"\n                alt=\"\"\n                style=\"\n                  width: 657px;\n                  display: block;\n                  margin-left: auto;\n                  margin-right: auto;\n                \"\n              />\n            </a>\n            <div style=\"text-align: center; margin-top: 26px\">\n              <a\n                class=\"btn\"\n                href=\"https://frontlinebusiness.com.ph/insight/DepEd%E2%80%99s%20Revamped%20Senior%20High%20School%20Curriculum:%20Enhancing%20Employability%20of%20SHS%20Graduates\"\n                style=\"\n                  display: inline-block;\n                  color: #dbd5d5;\n                  font-weight: 300;\n                  padding: 12px 50px;\n                  background: linear-gradient(to right, #d60070, #6a1142);\n                  border-radius: 5px;\n                  text-decoration: none;\n                  font-size: 12px;\n                \"\n                >Read more</a\n              >\n            </div>\n          </div>\n          <!-- FOOTER -->\n          <div\n            class=\"footer\"\n            style=\"padding: 32px 17px 48px; background-color: #333\"\n          >\n            <a href=\"\">\n              <img\n                src=\"https://lh3.googleusercontent.com/pw/AP1GczMwywpNwM3ypEY8Ex92PNahXs0Jghx8fViZ8RvD4Lej1JKn63j5hfcnM2MBrI_stYKXy9qVxg3CmRP9o3XiVnnumuCSiZe6fZTnkXIycFGNHBX7QS8=w2400\"\n                alt=\"\"\n                style=\"\n                  width: 200px;\n                  display: block;\n                  margin-left: auto;\n                  margin-right: auto;\n                \"\n              />\n            </a>\n            <h3 style=\"color: #fff; text-align: center; margin: 16px 0\">\n              Your Trusted Christian Partner <br />\n              in Managed Services\n            </h3>\n            <p\n              style=\"\n                color: #fff;\n                text-align: center;\n                font-size: 12px;\n                margin-bottom: 16px;\n              \"\n            >\n              We deliver end-to-end solutions and professional expertise in\n              <br />\n              web applications, websites, virtual assistants, and skills\n              development.\n            </p>\n            <div class=\"icons\" style=\"margin-bottom: 8px; text-align: center\">\n              <a\n                href=\"https://www.facebook.com/frontline.business\"\n                style=\"display: inline-block\"\n                ><img\n                  style=\"width: 25px; height: 25px\"\n                  src=\"https://lh3.googleusercontent.com/pw/AP1GczNEy4pqCkdZ3TI2U5_ty1rsyAr287bs1MKnE9is6Wfvg9JYCZ5AuEqQHD7jyKVINg7Oy2P6ntdVGi8qkzby1H4P2XlaoqSsrNkIQkQ9FyhWBea3x6E=s70-p-k\"\n                  alt=\"\"\n              /></a>\n              <a\n                href=\"https://www.linkedin.com/company/frontline-business-solutions-inc/\"\n                style=\"display: inline-block\"\n                ><img\n                  style=\"width: 25px; height: 25px\"\n                  src=\"https://lh3.googleusercontent.com/pw/AP1GczPi3buvL5Un9DyKoGLP0zaolXrXyV7hP8M8IwAcvxWiaysuZxscVzw9hReEoP5j5xr1-F3Fx1JI32UEmV3pv949c33m1JbEedeUHbxh1JrcxkHxlP8=s70-p-k\"\n                  alt=\"\"\n              /></a>\n              <a\n                href=\"https://www.youtube.com/@frontlinebusinesssolutions6578\"\n                style=\"display: inline-block\"\n                ><img\n                  style=\"width: 25px; height: 25px\"\n                  src=\"https://lh3.googleusercontent.com/pw/AP1GczOFaymIU4G3nFFhSiWbsv-JRGDD31-RCXOyDulqVuIEldQDH-04FJBepWSVQRk0iTxi1Pf4hY_SoNIEEdoWBxmWXAwLX3ePScXnh-LM5846LaM6O8s=s70-p-k\"\n                  alt=\"\"\n              /></a>\n              <a\n                href=\"https://www.instagram.com/frontline.business/\"\n                style=\"display: inline-block\"\n                ><img\n                  style=\"width: 25px; height: 25px\"\n                  src=\"https://lh3.googleusercontent.com/pw/AP1GczPPsABBWthmMwhMnRaz0NxOwLNe_F5dyau9JBbQUAbT48kN5S7WKa1_M6SSb6awE4kFyDiIKv7prYY2wCPNfYegju-Ph0xjM9khTrzBbAb0eY8AUwA=s70-p-k\"\n                  alt=\"\"\n              /></a>\n              <a\n                href=\"https://www.tiktok.com/@frontlinebusinessinc\"\n                style=\"display: inline-block\"\n                ><img\n                  style=\"width: 25px; height: 25px\"\n                  src=\"https://lh3.googleusercontent.com/pw/AP1GczNF50VT3hd-2PhvM_OUWALWmBgwrHp3drnQM-wGSSP5-C-RHXP-HePnxs4W-f8dDzun14Jth78npNTahLoR-9snETM5vsIPBBvdXzJfqPS8-eYZwiA=s70-p-k\"\n                  alt=\"\"\n              /></a>\n            </div>\n            <div style=\"text-align: center; line-height: 1\">\n              <p style=\"font-size: 16px; color: #fff\">\n                <small>\n                  Copyright 2025, All rights reserved. <br />\n                  Baloc Road, Brgy, San Ignacio, San Pablo City, Laguna\n                  Philippines 4000<br />\n                  <br />\n                  You are receiving this email because you opted in at our\n                  website. <br />\n                </small>\n              </p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  </body>\n</html>', 1, '3a34b34341be96bcb31dfe6ad1b14510949ffc9c561bb8d3cafbc7ed503e7fdd', '', '', 'Louren Isobel', 'developer', '2025-05-28 09:58:24', '2025-06-02 21:27:21'),
(40, 1, 13, 'louren.rubico@frontlinebusiness.com.ph', 'Test Email na ito', '<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <!--Dark Mode meta tags needed to enable Dark Mode in email client user agents-->\n    <meta name=\"color-scheme\" content=\"light dark\" />\n    <meta name=\"supported-color-schemes\" content=\"light dark only\" />\n    <title>Graphic Designing Using Adobe Photoshop</title>\n    <style>\n      :root {\n        color-scheme: light dark;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      body {\n        font-family: Arial, Helvetica, sans-serif !important;\n        color: #333;\n        overflow-x: hidden;\n      }\n      p,\n      h3,\n      ul li {\n        font-size: 18px;\n      }\n      .canvas {\n        width: 700px;\n        margin: 0 auto;\n        background-color: #f9f9f9;\n      }\n      table {\n        border-spacing: 0;\n      }\n      @media screen and (min-width: 340px) and (max-width: 520px) {\n        .canvas {\n          width: 100% !important;\n          background-color: #f9f9f9 !important;\n        }\n        .container {\n          width: 100% !important;\n          padding: 0 !important;\n          margin: 0 auto !important;\n        }\n        .seminar {\n          padding: 0 !important;\n        }\n      }\n    </style>\n  </head>\n  <body>\n    <section class=\"seminar\" style=\"background-color: #f2f2f2; padding: 0\">\n      <div\n        class=\"container\"\n        style=\"width: 700px; margin: 0 auto; background-color: white\"\n      >\n        <div class=\"canvas\">\n          <!--  -->\n          <div>\n            <a href=\"#\">\n              <img\n                src=\"https://lh3.googleusercontent.com/pw/AP1GczMcccmOdjTgavTvkai5G50UJ-pOQuaILSwN-PoMyNnnDJq-YG15msYSLQkiQVUGLllOQ-vKT0wuE-qi5brAJ5ZnYVbULKSTr-Ry8GyaO4aiPuQJao0=w2400\"\n                alt=\"hero-img\"\n                style=\"width: 100%; height: auto; display: block\"\n            /></a>\n          </div>\n          <!-- INTRODUCTION -->\n          <div\n            class=\"theIntroduction\"\n            style=\"padding: 32px 48px; background-color: white\"\n          >\n            <p style=\"margin-bottom: 10px\">Dear Participant,</p>\n            <p>\n              We have reserved a slot for you in our\n              <b\n                >FACE-TO-FACE TRAINING IN GRAPHIC DESIGNING USING ADOBE\n                PHOTOSHOP</b\n              >, as part of the <b>Learning Center Solutions</b> program designed\n              for beginners and intermediate learners—including students,\n              creative professionals, and career shifters interested in graphic\n              design.\n            </p>\n          </div>\n          <!-- DESC -->\n          <div\n            class=\"theDescription\"\n            style=\"padding: 0 48px; background-color: white\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                margin-bottom: 30px;\n                font-size: 28px;\n                font-weight: 900;\n                text-transform: uppercase;\n                color: #0e6cab;\n                font-family: Arial, sans-serif;\n                text-align: center;\n              \"\n            >\n              DESCRIPTION\n            </h2>\n\n            <p style=\"margin-top: 30px\">\n              Adobe Photoshop remains one of the most powerful and widely-used\n              tools for graphic design. This training is designed to walk you\n              through the essential tools and features used by professionals to\n              create stunning visuals, digital artwork, and promotional\n              materials.\n            </p>\n            <p style=\"margin-top: 30px\">\n              In this session, you will learn how to navigate the Photoshop\n              interface, work with layers and masks, perform photo editing and\n              retouching, use typography effectively, and create engaging\n              layouts for both print and digital media. The training includes\n              guided activities and real-time feedback from experienced trainers\n              to ensure you gain both confidence and creativity using Photoshop.\n            </p>\n            <p style=\"margin-top: 30px\">\n              Whether you\'re looking to build a career in design or simply\n              enhance your digital skills, this face-to-face crash course will\n              give you a solid foundation in one of the most essential tools in\n              the creative industry.\n            </p>\n          </div>\n          <!-- TOPIC OUTLINE -->\n          <div\n            class=\"theIntroduction\"\n            style=\"padding: 32px 48px; background-color: white\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                margin-bottom: 30px;\n                font-size: 28px;\n                font-weight: 900;\n                text-transform: uppercase;\n                color: #0e6cab;\n                font-family: Arial, sans-serif;\n                text-align: center;\n              \"\n            >\n              Seminar Highlights\n            </h2>\n            <ul style=\"display: block; max-width: fit-content; margin: 0 auto\">\n              <li>Introduction & Orientation</li>\n              <li>Getting Started with Photoshop</li>\n              <li>Working with Layers and Basic Editing</li>\n              <li>Text & Typography Design</li>\n              <li>Using Shapes, Icons, and Graphics</li>\n              <li>Applying Filters & Effects</li>\n              <li>\n                Design Mini-Project: Social Media Post <br />\n                or Simple Banner\n              </li>\n              <li>Sharing Outputs & Wrap-Up</li>\n            </ul>\n          </div>\n          <!-- IMPORTANT RULES AND REMINDERS -->\n          <div\n            class=\"theRules\"\n            style=\"padding: 0 48px; background-color: white\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                margin-bottom: 30px;\n                font-size: 28px;\n                font-weight: 900;\n                text-transform: uppercase;\n                color: #0e6cab;\n                font-family: Arial, sans-serif;\n                text-align: center;\n              \"\n            >\n              IMPORTANT RULES AND REMINDERS\n            </h2>\n            <div>\n              <h3 style=\"margin-bottom: 10px\">What to Expect</h3>\n              <ul\n                style=\"\n                  display: block;\n                  max-width: fit-content;\n                  margin: 0px auto 30px auto;\n                \"\n              >\n                <li>\n                  All necessary equipment will be provided for you, including\n                  computers with Adobe Photoshop installed.\n                </li>\n                <li>\n                  Gain practical, hands-on experience in graphic design by\n                  applying the principles and techniques learned throughout the\n                  training.\n                </li>\n                <li>Expect in-depth discussions and real-world examples.</li>\n              </ul>\n            </div>\n            <div>\n              <h3 style=\"margin-bottom: 10px\">Punctuality</h3>\n              <p style=\"margin-bottom: 30px\">\n                Please arrive on time. Late arrivals may miss important\n                instructions and hands-on exercises. We want you to get the most\n                out of this session.\n              </p>\n            </div>\n            <div>\n              <h3 style=\"margin-bottom: 10px\">Participation</h3>\n              <p style=\"margin-bottom: 30px\">\n                This is an interactive training. Active participation is\n                encouraged. Engage with your trainer, ask questions, and take\n                advantage of the real-time support available to you.\n              </p>\n            </div>\n            <div>\n              <h3 style=\"margin-bottom: 10px\">Break Schedule</h3>\n              <p style=\"margin-bottom: 30px\">\n                A 15-minute break will be given midway through the session. Use\n                this time to relax, hydrate, and recharge.\n              </p>\n            </div>\n            <div>\n              <h3 style=\"margin-bottom: 10px\">Respect and Professionalism</h3>\n              <p style=\"margin-bottom: 30px\">\n                Maintain a respectful and professional attitude throughout the\n                training. Be courteous to your trainers and fellow participants,\n                and use appropriate language in all interactions.\n              </p>\n            </div>\n            <div>\n              <h3 style=\"margin-bottom: 10px\">Attendance & Certification</h3>\n              <p style=\"margin-bottom: 30px\">\n                A roll-call will be conducted at the end of the course. Only\n                participants who are present and actively participating will\n                receive a Certificate of Completion.\n              </p>\n            </div>\n\n            <p style=\"padding-bottom: 32px\">\n              For any additional information or inquiries, please feel free to\n              reach out to the official focal person,\n              <b>Ms. Thea Lyzette Consignado</b>, at the following email\n              address: <b>thea.consignado@frontlinebusiness.com.ph</b>. She will\n              be more than happy to assist you with any questions you may have.\n            </p>\n          </div>\n          <!-- REMINDER -->\n          <div\n            style=\"\n              padding: 32px 48px;\n              background-color: white;\n              border-top: 2px solid #e2dfdf;\n              border-bottom: 2px solid #e2dfdf;\n            \"\n          >\n            <small\n              ><i\n                >Please note that registration fees are non-refundable. However,\n                if a registered attendee is unable to participate in the crash\n                course after successful registration, the slot is transferable\n                to another person. To facilitate this transfer, the new attendee\n                must inform the secretariat of Frontline Business Solutions\n                about the slot transfer before the scheduled event date. We\n                appreciate your understanding and cooperation in this matter.\n              </i></small\n            >\n          </div>\n        </div>\n        <!-- FOOTER -->\n        <div class=\"footer\" style=\"padding: 48px; background-color: white\">\n          <div class=\"icons\" style=\"margin-bottom: 8px; text-align: center\">\n            <a\n              href=\"https://www.facebook.com/frontline.business\"\n              style=\"display: inline-block\"\n              ><img\n                style=\"width: 25px; height: 25px\"\n                src=\"https://lh3.googleusercontent.com/pw/AP1GczNEy4pqCkdZ3TI2U5_ty1rsyAr287bs1MKnE9is6Wfvg9JYCZ5AuEqQHD7jyKVINg7Oy2P6ntdVGi8qkzby1H4P2XlaoqSsrNkIQkQ9FyhWBea3x6E=s70-p-k\"\n                alt=\"\"\n            /></a>\n            <a\n              href=\"https://www.linkedin.com/company/frontline-business-solutions-inc/\"\n              style=\"display: inline-block\"\n              ><img\n                style=\"width: 25px; height: 25px\"\n                src=\"https://lh3.googleusercontent.com/pw/AP1GczPi3buvL5Un9DyKoGLP0zaolXrXyV7hP8M8IwAcvxWiaysuZxscVzw9hReEoP5j5xr1-F3Fx1JI32UEmV3pv949c33m1JbEedeUHbxh1JrcxkHxlP8=s70-p-k\"\n                alt=\"\"\n            /></a>\n            <a\n              href=\"https://www.youtube.com/@frontlinebusinesssolutions6578\"\n              style=\"display: inline-block\"\n              ><img\n                style=\"width: 25px; height: 25px\"\n                src=\"https://lh3.googleusercontent.com/pw/AP1GczOFaymIU4G3nFFhSiWbsv-JRGDD31-RCXOyDulqVuIEldQDH-04FJBepWSVQRk0iTxi1Pf4hY_SoNIEEdoWBxmWXAwLX3ePScXnh-LM5846LaM6O8s=s70-p-k\"\n                alt=\"\"\n            /></a>\n            <a\n              href=\"https://www.instagram.com/frontline.business/\"\n              style=\"display: inline-block\"\n              ><img\n                style=\"width: 25px; height: 25px\"\n                src=\"https://lh3.googleusercontent.com/pw/AP1GczPPsABBWthmMwhMnRaz0NxOwLNe_F5dyau9JBbQUAbT48kN5S7WKa1_M6SSb6awE4kFyDiIKv7prYY2wCPNfYegju-Ph0xjM9khTrzBbAb0eY8AUwA=s70-p-k\"\n                alt=\"\"\n            /></a>\n            <a\n              href=\"https://www.tiktok.com/@frontlinebusinessinc\"\n              style=\"display: inline-block\"\n              ><img\n                style=\"width: 25px; height: 25px\"\n                src=\"https://lh3.googleusercontent.com/pw/AP1GczNF50VT3hd-2PhvM_OUWALWmBgwrHp3drnQM-wGSSP5-C-RHXP-HePnxs4W-f8dDzun14Jth78npNTahLoR-9snETM5vsIPBBvdXzJfqPS8-eYZwiA=s70-p-k\"\n                alt=\"\"\n            /></a>\n          </div>\n          <div style=\"text-align: center; line-height: 1; padding-bottom: 20px\">\n            <p style=\"font-family: \'Poppins\', sans-serif\">\n              <small>\n                Frontline Business Solutions Inc. <br />\n                Baloc Road, Brgy. San Ignacio <br />\n                San Pablo City Laguna 4000 Philippines <br />\n                <a href=\"https://frontlinebusiness.com.ph/\"\n                  >frontlinebusiness.com.ph</a\n                >\n              </small>\n            </p>\n          </div>\n        </div>\n      </div>\n    </section>\n  </body>\n</html>', 1, '3a34b34341be96bcb31dfe6ad1b14510949ffc9c561bb8d3cafbc7ed503e7fdd', '', '', 'Louren Isobel', 'developer', '2025-05-28 09:59:27', '2025-06-02 21:20:38');
