INSERT INTO `fbsv2_services_payroll_overview` (`payroll_overview_aid`, `payroll_overview_subtitle`, `payroll_overview_title`, `payroll_overview_img`, `payroll_overview_list_title_a`, `payroll_overview_list_description_a`, `payroll_overview_list_title_b`, `payroll_overview_list_description_b`, `payroll_overview_list_title_c`, `payroll_overview_list_description_c`, `payroll_overview_created`, `payroll_overview_datetime`) VALUES
(1, 'Why Choose Our', 'Online Payroll System', '[{\"name\":\"payroll-ss.png\",\"id\":\"1JFiU11yjXDrC9ABTFdWIxSQ5aU0zJFsK\",\"datetime\":\"2025-05-22 17:02:07\"}]', 'Enhanced Accuracy and Reduced Errors', 'Our system automates payroll calculations, ensuring precise processing of hours worked, overtime, and deductions. This minimizes payroll disputes and errors, increasing employee satisfaction and reducing administrative workload.', 'Cost Efficiency and Compliance', 'Centralized payroll management reduces administrative costs and ensures compliance with local labor laws and tax regulations. This saves time, reduces potential penalties, and enhances trust among employees by ensuring accurate and timely compensation.', 'Secure and Transparent Payroll', 'With robust security features, our system protects sensitive employee and financial data while maintaining accurate, compliant payroll processes. This fosters trust among stakeholders by guaranteeing transparency and data protection.', '2025-05-22 17:02:04', '2025-05-23 07:48:16');

